using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using UnityEditor;using UnityEditor.SceneManagement;using MapSharedProps.EditorTools;using MapTunnels.EditorTools;
public static class Lantern172ShaderChecks{
 static string Root=>Path.GetDirectoryName(Application.dataPath);static string Out=>Path.Combine(Root,"Evidence172");
