 static Texture2D Shot(Camera c,string name){var im=Shared117Review.Image(c,960,640);File.WriteAllBytes(Path.Combine(Out,name+".png"),im.EncodeToPNG());return im;}
 static Row Compare(Camera c,string path,string mode,Material[] mats,string name){foreach(var m in mats)m.shader=Shader.Find("Review/TunnelBefore164");var before=Shot(c,path+"-"+name+"-before");foreach(var m in mats)m.shader=Shader.Find("MapTunnels/Tunnel");var after=Shot(c,path+"-"+name+"-after");var a=before.GetPixels32();var b=after.GetPixels32();long sum=0,sa=0,sb=0;int changed=0,max=0;for(int i=0;i<a.Length;i++){int d=Math.Max(Math.Abs(a[i].r-b[i].r),Math.Max(Math.Abs(a[i].g-b[i].g),Math.Abs(a[i].b-b[i].b)));if(d>0)changed++;max=Math.Max(max,d);sum+=Math.Abs(a[i].r-b[i].r)+Math.Abs(a[i].g-b[i].g)+Math.Abs(a[i].b-b[i].b);sa+=a[i].r+a[i].g+a[i].b;sb+=b[i].r+b[i].g+b[i].b;}UnityEngine.Object.DestroyImmediate(before);UnityEngine.Object.DestroyImmediate(after);return new Row{path=path,mode=mode,stage=name,changed=changed,maxDelta=max,meanDelta=(double)sum/(a.Length*3),beforeMean=(double)sa/(a.Length*3),afterMean=(double)sb/(a.Length*3)};}
