 public static void Run(){Directory.CreateDirectory(Out);var oldG=GraphicsSettings.defaultRenderPipeline;var oldQ=QualitySettings.renderPipeline;var rows=new List<Row>();var errors=new List<string>();try{foreach(int mode in new[]{0,2}){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var field=MapTunnelBuilder.Build(Path.Combine(Root,"Input123Mine"),null,null,"Lantern172");if(!field.built)throw new Exception(field.message);field.root.SetActive(false);var renderer=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<UniversalRendererData>("Assets/Settings/PC_Renderer.asset"));renderer.name="Temporary shader check "+mode;var rd=new SerializedObject(renderer);rd.FindProperty("m_RenderingMode").intValue=mode;rd.ApplyModifiedPropertiesWithoutUndo();var pipe=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>("Assets/Settings/PC_RPAsset.asset"));var so=new SerializedObject(pipe);var arr=so.FindProperty("m_RendererDataList");arr.arraySize=1;arr.GetArrayElementAtIndex(0).objectReferenceValue=renderer;so.FindProperty("m_DefaultRendererIndex").intValue=0;so.FindProperty("m_AdditionalLightsRenderingMode").intValue=1;so.FindProperty("m_AdditionalLightShadowsSupported").boolValue=true;so.FindProperty("m_MainLightShadowsSupported").boolValue=true;so.ApplyModifiedPropertiesWithoutUndo();GraphicsSettings.defaultRenderPipeline=pipe;QualitySettings.renderPipeline=pipe;
 var c=new GameObject("offscreen camera").AddComponent<Camera>();c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=Color.black;c.fieldOfView=45;c.nearClipPlane=.03f;c.farClipPlane=60;c.transform.position=new Vector3(4,4,-6);c.transform.LookAt(new Vector3(0,1,0));c.gameObject.AddComponent<UniversalAdditionalCameraData>().renderPostProcessing=false;
 var mat=new Material(Shader.Find("MapTunnels/Tunnel"));Block("floor",new Vector3(0,-.1f,0),new Vector3(8,.2f,8),mat);Block("wall",new Vector3(0,1.5f,1),new Vector3(4,3,.2f),mat);Block("occluder",new Vector3(0,1,-.5f),new Vector3(.6f,2,.6f),mat);Block("roof cut",new Vector3(0,2.8f,.2f),new Vector3(3,.2f,2),mat);
 var sun=new GameObject("main").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=1;sun.transform.rotation=Quaternion.Euler(45,-35,0);sun.shadowBias=.02f;sun.shadowNormalBias=.02f;RenderSettings.sun=sun;
 var point=new GameObject("point").AddComponent<Light>();point.type=LightType.Point;point.transform.position=new Vector3(-1.4f,1.5f,-1.8f);point.range=7;point.intensity=5;point.color=new Color(1,.72f,.36f);point.shadowCustomResolution=512;point.shadowBias=.02f;point.shadowNormalBias=.015f;
 foreach(string stage in new[]{"main-no-shadow","main-shadow","SH-only","all-off","cutaway-main-shadow","point-no-shadow","point-shadow","cutaway-point-shadow"}){sun.enabled=stage.StartsWith("main")||stage=="cutaway-main-shadow";sun.shadows=stage=="main-no-shadow"?LightShadows.None:LightShadows.Soft;point.enabled=stage.Contains("point");point.shadows=stage=="point-no-shadow"?LightShadows.None:LightShadows.Soft;SH(stage=="SH-only"?.18f:0);Shader.SetGlobalVector("_MapCutA",stage.StartsWith("cutaway")?new Vector4(0,0,0,2.1f):Vector4.zero);Shader.SetGlobalVector("_MapCutB",c.transform.position);var row=Compare(c,mode==0?"Forward":"ForwardPlus",renderer.renderingMode.ToString(),new[]{mat},stage);var actual=pipe.scriptableRenderer.GetType().GetProperty("renderingModeActual",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(pipe.scriptableRenderer).ToString();row.mode=actual;rows.Add(row);if((stage=="SH-only"||stage=="all-off"||stage=="main-no-shadow")&&row.maxDelta>1)errors.Add(mode+" unexpected baseline difference "+stage);}
