 var mats=field.root.GetComponentsInChildren<Renderer>().SelectMany(r=>r.sharedMaterials).Where(m=>m&&m.shader.name=="MapTunnels/Tunnel").Distinct().Select(m=>{var clone=new Material(m);foreach(var rr in field.root.GetComponentsInChildren<Renderer>()){var mm=rr.sharedMaterials;for(int j=0;j<mm.Length;j++)if(mm[j]==m)mm[j]=clone;rr.sharedMaterials=mm;}return clone;}).ToArray();
 foreach(var l in UnityEngine.Object.FindObjectsByType<Light>(FindObjectsSortMode.None))l.enabled=false;var lamp=new GameObject("test point").AddComponent<Light>();lamp.type=LightType.Point;lamp.transform.position=new Vector3(12.67f,1.51f,11.4f);lamp.intensity=3.2f;lamp.color=new Color(1,.72f,.36f);lamp.range=5.5f;lamp.shadows=LightShadows.Soft;lamp.shadowCustomResolution=256;c.transform.position=new Vector3(12,9,5.1f);c.transform.LookAt(new Vector3(12,.5f,11.4f));SH(.06f);Shader.SetGlobalVector("_MapCutA",new Vector4(12,0,11.4f,7f));Shader.SetGlobalVector("_MapCutB",c.transform.position);var fieldRow=Compare(c,mode==0?"Forward":"ForwardPlus",renderer.renderingMode.ToString(),mats,"actual-mine-point");rows.Add(fieldRow);if(fieldRow.afterMean<.5)errors.Add("actual mine image too dark to validate "+mode);
 GraphicsSettings.defaultRenderPipeline=oldG;QualitySettings.renderPipeline=oldQ;UnityEngine.Object.DestroyImmediate(pipe);UnityEngine.Object.DestroyImmediate(renderer);}
 foreach(var shader in new[]{Shader.Find("MapTunnels/Tunnel"),Shader.Find("Review/TunnelBefore164")})foreach(var m in ShaderUtil.GetShaderMessages(shader).Where(m=>m.severity==UnityEditor.Rendering.ShaderCompilerMessageSeverity.Error))errors.Add(m.message);File.WriteAllText(Path.Combine(Out,"shader.json"),JsonUtility.ToJson(new Report{completed=true,rows=rows.ToArray(),errors=errors.ToArray()},true));EditorApplication.Exit(errors.Count==0?0:1);
 }catch(Exception e){File.WriteAllText(Path.Combine(Out,"error.txt"),e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}finally{GraphicsSettings.defaultRenderPipeline=oldG;QualitySettings.renderPipeline=oldQ;}}
